import{services,money,today,load,save,conflicts,validHours,escapeHTML as esc}from'./model.js';
const $=s=>document.querySelector(s);const content=$('#admin-content');let state=load(),view=location.hash.slice(1)||'overview',search='',timer;
const titles={overview:'Рабочий день<br>начинается здесь.',bookings:'Расписание<br>вашего салона.',clients:'Каждый клиент —<br>особенный.',finance:'Финансы.<br>Всё на виду.',schedule:'Ваш ритм.<br>Ваши правила.'};const labels={overview:'Обзор',bookings:'Записи',clients:'Клиенты',finance:'Финансы',schedule:'Режим работы'};if(!labels[view])view='overview';
const nameService=id=>services.find(s=>s.id===id)?.name||id;const dateRU=d=>new Intl.DateTimeFormat('ru',{day:'numeric',month:'short',timeZone:'UTC'}).format(new Date(d+'T12:00:00Z'));const statusNames={confirmed:'Записан',completed:'Завершён',cancelled:'Отменён'};const normalized=p=>p.replace(/\D/g,'');
function feedback(s){clearTimeout(timer);$('#admin-feedback').textContent=s;timer=setTimeout(()=>$('#admin-feedback').textContent='',6000)}
async function mutate(fn){const op=()=>{const s=load();fn(s);save(s);state=s};try{if(navigator.locks)await navigator.locks.request('cult-demo-write',op);else op();return true}catch(e){feedback(e.message||'Не удалось сохранить изменения.');return false}}
function kpi(label,value,note,target){return `<button class="kpi" data-view="${target}"><label>${label}</label><strong>${value}</strong><small>${note}</small></button>`}
function toolbar(title,sub,tools=''){return `<div class="table-toolbar"><div><h2>${title}</h2>${sub?`<p>${sub}</p>`:''}</div><div class="tools">${tools}</div></div>`}
const empty=(n,title,sub)=>`<tr><td colspan="${n}" class="empty-table"><strong>${title}</strong>${sub}</td></tr>`;
function bookingRows(rows,actions=true){return rows.map(b=>`<tr><td>${dateRU(b.date)}<small>${b.time}</small></td><td><button class="row-action" data-client="${esc(normalized(b.phone))}">${esc(b.name)}</button><small>${esc(b.phone)}</small></td><td>${esc(nameService(b.service))}<small>${b.duration} мин</small></td><td>${money(b.price)}</td><td><span class="status-tag ${b.status==='completed'?'done':''}">${statusNames[b.status]}</span></td><td>${money(b.paid)}<small>${b.paid>=b.price?'Оплачено':'Не оплачено полностью'}</small></td>${actions?`<td>${b.status==='confirmed'?`<button data-complete="${b.id}">Завершить</button><button data-cancel="${b.id}">Отменить</button>`:b.status==='completed'&&b.paid<b.price?`<button data-pay="${b.id}">Оплата</button>`:'—'}</td>`:''}</tr>`).join('')||empty(actions?7:6,'Здесь появятся ваши записи','Создайте пробную запись через форму на сайте.');}
function bookingsTable(rows,actions=true){return `<div class="table-scroll"><table><thead><tr><th>Дата / время</th><th>Клиент</th><th>Услуга</th><th>Сумма</th><th>Визит</th><th>Оплата</th>${actions?'<th>Действия</th>':''}</tr></thead><tbody>${bookingRows(rows,actions)}</tbody></table></div>`}
function clients(){const map=new Map;for(const b of state.bookings){const key=normalized(b.phone);if(!map.has(key))map.set(key,{key,name:b.name,phone:b.phone,rows:[]});map.get(key).rows.push(b)}return [...map.values()]}
function switchView(v){view=labels[v]?v:'overview';search='';location.hash=view;render();window.scrollTo({top:0,behavior:'instant'})}
function render(){state=load();$('#admin-title').innerHTML=titles[view];$('#breadcrumb').textContent=labels[view];document.querySelectorAll('.sidebar [data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===view));({overview,bookings,clients:clientView,finance,schedule})[view]()}
function overview(){const active=state.bookings.filter(b=>b.status!=='cancelled'),completed=active.filter(b=>b.status==='completed'),paid=state.bookings.reduce((a,b)=>a+b.paid,0),expense=state.expenses.reduce((a,b)=>a+b.amount,0),upcoming=active.filter(b=>b.status==='confirmed'&&b.date>=today()).sort((a,b)=>(a.date+a.time).localeCompare(b.date+b.time));content.innerHTML=`<div class="kpi-grid">${kpi('Записи сегодня',active.filter(b=>b.date===today()).length,'По местному времени салона','bookings')}${kpi('Выручка',money(completed.reduce((a,b)=>a+b.price,0)),'Завершённые услуги · за всё время','finance')}${kpi('Получено',money(paid),'Учтённые оплаты · за всё время','finance')}${kpi('Расходы',money(expense),'Оплаченные расходы · за всё время','finance')}</div><section class="panel table-panel">${toolbar('Ближайшие визиты','Пробные записи из формы на сайте',`<button class="compact-button" data-view="bookings">Все записи ↗</button>`)}${bookingsTable(upcoming.slice(0,6))}</section><div class="lower-grid"><section class="panel mini-panel"><p class="eyebrow">РАСПИСАНИЕ</p><h3>Обычный график. Личные исключения.</h3><p>Настройте неделю один раз и меняйте часы отдельных дней. Календарик записи сразу учитывает изменения.</p><button class="compact-button" data-view="schedule">Настроить режим работы ↗</button></section><section class="panel mini-panel"><p class="eyebrow">ПЕРВАЯ ЗАГОТОВКА</p><h3>Проверим путь клиента?</h3><p>Создайте запись на сайте, завершите визит и отметьте оплату. Здесь появятся клиент и финансовые показатели.</p><a class="text-link" href="index.html#reserva">Перейти к форме записи <span>↗</span></a></section></div>`}
function bookings(){let rows=state.bookings.filter(b=>(b.name+' '+b.phone+' '+nameService(b.service)).toLowerCase().includes(search.toLowerCase())).sort((a,b)=>(a.date+a.time).localeCompare(b.date+b.time));content.innerHTML=`<section class="panel table-panel">${toolbar('Все записи',`${state.bookings.length} записей · демонстрационные данные`,`<input id="search" aria-label="Поиск записей" placeholder="Клиент или услуга…" value="${esc(search)}">`)}${bookingsTable(rows)}</section>`;bindSearch()}
function bindSearch(){$('#search').oninput=e=>{const pos=e.target.selectionStart;search=e.target.value;view==='bookings'?bookings():clientView();$('#search').focus();$('#search').setSelectionRange(pos,pos)}}
function clientView(){const rows=clients().filter(c=>(c.name+' '+c.phone).toLowerCase().includes(search.toLowerCase()));content.innerHTML=`<section class="panel table-panel">${toolbar('Клиентская база','Карточка создаётся после пробной записи',`<input id="search" aria-label="Поиск клиентов" placeholder="Имя или телефон…" value="${esc(search)}">`)}<div class="table-scroll"><table><thead><tr><th>Клиент</th><th>Контакт</th><th>Визитов</th><th>Последний визит</th><th>Получено</th><th>Остаток к оплате</th></tr></thead><tbody>${rows.map(c=>{const done=c.rows.filter(b=>b.status==='completed').sort((a,b)=>b.date.localeCompare(a.date));return `<tr><td><button class="row-action" data-client="${esc(c.key)}">${esc(c.name)}</button></td><td>${esc(c.phone)}</td><td>${done.length}</td><td>${done[0]?dateRU(done[0].date):'—'}</td><td>${money(c.rows.reduce((a,b)=>a+b.paid,0))}</td><td>${money(done.reduce((a,b)=>a+Math.max(0,b.price-b.paid),0))}</td></tr>`}).join('')||empty(6,'Начните историю отношений','Клиенты появятся здесь после пробной записи.')}</tbody></table></div></section>`;bindSearch()}
function showClient(key){const c=clients().find(c=>c.key===key);if(!c)return;$('#client-detail').innerHTML=`<p class="eyebrow">КАРТОЧКА КЛИЕНТА · ДЕМО</p><h2>${esc(c.name)}</h2><div class="detail-line"><span>Телефон</span><span>${esc(c.phone)}</span></div><div class="detail-line"><span>Всего записей</span><span>${c.rows.length}</span></div><h3 style="margin-top:28px">История посещений</h3><div class="table-scroll"><table><thead><tr><th>Дата</th><th>Услуга</th><th>Статус</th><th>Оплачено</th></tr></thead><tbody>${c.rows.map(b=>`<tr><td>${dateRU(b.date)}<small>${b.time}</small></td><td>${esc(nameService(b.service))}</td><td>${statusNames[b.status]}</td><td>${money(b.paid)}</td></tr>`).join('')}</tbody></table></div>`;$('#client-dialog').showModal()}
function finance(){const payments=state.bookings.filter(b=>b.paid>0),received=payments.reduce((a,b)=>a+b.paid,0),expenses=state.expenses.reduce((a,b)=>a+b.amount,0);content.innerHTML=`<div class="kpi-grid">${kpi('Получено',money(received),'Все пробные оплаты','finance')}${kpi('Расходы',money(expenses),'Все пробные расходы','finance')}${kpi('Разница',money(received-expenses),'Поступления минус выплаты','finance')}${kpi('Остаток к оплате',money(state.bookings.filter(b=>b.status==='completed').reduce((a,b)=>a+Math.max(0,b.price-b.paid),0)),'По завершённым визитам','finance')}</div><section class="panel table-panel">${toolbar('Оплаты клиентов','Упрощённый учёт · без выпуска фискальных документов',`<button class="compact-button" id="export-csv">Экспорт CSV ↓</button>`)}<div class="table-scroll"><table><thead><tr><th>Дата оплаты</th><th>Клиент</th><th>Услуга</th><th>Сумма</th><th>Способ</th></tr></thead><tbody>${payments.map(b=>`<tr><td>${dateRU(b.paidDate||b.date)}</td><td>${esc(b.name)}</td><td>${esc(nameService(b.service))}</td><td>${money(b.paid)}</td><td>Демо-оплата</td></tr>`).join('')||empty(5,'Оплат пока нет','Завершите пробный визит и нажмите «Оплата» в разделе записей.')}</tbody></table></div></section><section class="panel table-panel">${toolbar('Расходы','Добавьте вымышленный расход для проверки отчёта')}<form id="expense-form" class="inline-form"><label>Дата<input type="date" name="date" required value="${today()}"></label><label>Категория<select name="category"><option>Материалы</option><option>Аренда</option><option>Реклама</option><option>Прочее</option></select></label><label>Описание<input name="description" required maxlength="100" placeholder="Тестовый расход"></label><label>Сумма, €<input type="number" name="amount" min="0.01" max="100000" step="0.01" required placeholder="0,00"></label><button class="compact-button">+ Добавить</button></form><div class="table-scroll"><table><thead><tr><th>Дата</th><th>Категория</th><th>Описание</th><th>Сумма</th></tr></thead><tbody>${state.expenses.map(x=>`<tr><td>${dateRU(x.date)}</td><td>${esc(x.category)}</td><td>${esc(x.description)}</td><td>${money(x.amount)}</td></tr>`).join('')||empty(4,'Расходы пока не добавлены','Все суммы в этом прототипе предназначены только для демонстрации.')}</tbody></table></div></section>`;$('#expense-form').onsubmit=async e=>{e.preventDefault();const d=new FormData(e.currentTarget);if(!d.get('description').trim())return feedback('Добавьте описание расхода.');if(await mutate(s=>s.expenses.push({id:crypto.randomUUID(),date:d.get('date'),category:d.get('category'),description:d.get('description').trim(),amount:Math.round(Number(d.get('amount'))*100)/100}))){render();feedback('Пробный расход добавлен.')}};$('#export-csv').onclick=exportCSV}
const days=['Воскресенье','Понедельник','Вторник','Среда','Четверг','Пятница','Суббота'];
function schedule(){content.innerHTML=`<p class="settings-note">Стартовый график — демонстрационный: пн–сб, 10:00–19:00, перерыв 14:00–15:00. Изменения сохраняются в этом браузере и влияют на форму записи. Между клиентами — 15 минут.</p><form id="week-form" class="panel table-panel">${toolbar('Режим работы по умолчанию','Повторяется каждую неделю; реальные часы ещё не утверждены')}<div class="table-scroll"><table class="schedule-table"><thead><tr><th>День недели</th><th>Рабочий</th><th>Открытие</th><th>Закрытие</th><th>Перерыв с</th><th>Перерыв до</th></tr></thead><tbody>${[1,2,3,4,5,6,0].map(i=>{const c=state.week[i];return `<tr><td>${days[i]}</td><td><input aria-label="${days[i]}: рабочий день" type="checkbox" name="open-${i}" ${c.open?'checked':''}></td>${['start','end','breakStart','breakEnd'].map((k,n)=>`<td><input type="time" aria-label="${days[i]}: ${['открытие','закрытие','начало перерыва','конец перерыва'][n]}" name="${k}-${i}" value="${c[k]}" ${n<2?'required':''}></td>`).join('')}</tr>`}).join('')}</tbody></table></div><div class="table-actions"><small>Чтобы убрать перерыв, очистите оба его поля.</small><button class="button light" style="padding:10px 17px;min-height:40px">Сохранить график</button></div></form><section class="panel table-panel">${toolbar('Ручная корректировка','Изменение конкретной даты имеет приоритет над обычной неделей')}<form id="exception-form" class="inline-form"><label>Дата<input type="date" name="date" min="${today()}" value="${today()}" required></label><label>Режим<select name="mode" id="exception-mode"><option value="closed">Выходной</option><option value="open">Другие часы</option></select></label><label>С<input type="time" name="start" value="10:00" required disabled></label><label>До<input type="time" name="end" value="17:00" required disabled></label><button class="compact-button">Сохранить исключение</button></form><div class="table-scroll"><table><thead><tr><th>Дата</th><th>Режим</th><th>Часы</th><th>Действие</th></tr></thead><tbody>${Object.entries(state.exceptions).sort(([a],[b])=>a.localeCompare(b)).map(([d,c])=>`<tr><td>${dateRU(d)}</td><td>${c.open?'Другие часы':'Выходной'}</td><td>${c.open?c.start+'–'+c.end:'Закрыто'}</td><td><button data-reset-day="${d}">Вернуть обычный график</button></td></tr>`).join('')||empty(4,'Особых дней пока нет','Добавьте выходной, сокращённый или дополнительный рабочий день.')}</tbody></table></div></section>`;
$('#week-form').onsubmit=async e=>{e.preventDefault();const data=new FormData(e.currentTarget);const week=Array.from({length:7},(_,i)=>({open:data.has('open-'+i),start:data.get('start-'+i),end:data.get('end-'+i),breakStart:data.get('breakStart-'+i),breakEnd:data.get('breakEnd-'+i)}));if(week.some(c=>!validHours(c)))return feedback('Проверьте часы: начало раньше окончания, перерыв внутри рабочего дня.');if(await mutate(s=>{s.week=week;rejectConflicts(s)})){render();feedback('Обычный график сохранён. Календарик обновлён.')}};
$('#exception-mode').onchange=e=>{const f=$('#exception-form');f.elements.start.disabled=f.elements.end.disabled=e.target.value==='closed'};
$('#exception-form').onsubmit=async e=>{e.preventDefault();const d=new FormData(e.currentTarget),key=d.get('date'),c={open:d.get('mode')==='open',start:d.get('start')||'',end:d.get('end')||'',breakStart:'',breakEnd:''};if(!validHours(c))return feedback('Окончание рабочего дня должно быть позже начала.');if(state.exceptions[key]&&!confirm('Заменить существующее исключение для этой даты?'))return;if(await mutate(s=>{s.exceptions[key]=c;rejectConflicts(s)})){render();feedback('Ручная корректировка сохранена.')}}}
function rejectConflicts(s){const c=conflicts(s);if(c.length)throw Error(`Изменение не сохранено: ${c.length} записей вне новых часов. Первая: ${c[0].date} ${c[0].time}. Сначала отмените пробную запись или измените часы.`)}
function exportCSV(){const rows=[['Тип','Дата','Описание','Сумма EUR'],...state.bookings.filter(b=>b.paid>0).map(b=>['Оплата',b.paidDate||b.date,nameService(b.service),b.paid.toFixed(2)]),...state.expenses.map(x=>['Расход',x.date,x.category+': '+x.description,x.amount.toFixed(2)])];const cell=x=>{let s=String(x);if(/^[=+\-@\t\r]/.test(s))s="'"+s;return '"'+s.replaceAll('"','""')+'"'};const blob=new Blob(['\ufeff'+rows.map(r=>r.map(cell).join(';')).join('\r\n')],{type:'text/csv;charset=utf-8'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='cult-spain-demo-finance.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),2000);feedback('Выгружены демонстрационные операции за всё время.')}
document.addEventListener('click',async e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.view){switchView(b.dataset.view);return}if(b.dataset.client){showClient(b.dataset.client);return}if(b.dataset.complete){if(await mutate(s=>{const r=s.bookings.find(x=>x.id===b.dataset.complete);if(r?.status==='confirmed')r.status='completed'})){render();feedback('Пробный визит завершён. Оплата отмечается отдельно.')}return}if(b.dataset.pay){if(await mutate(s=>{const r=s.bookings.find(x=>x.id===b.dataset.pay);if(r?.status==='completed'){r.paid=r.price;r.paidDate=today()}})){render();feedback('Полная демо-оплата учтена. Реальный платёж не выполнялся.')}return}if(b.dataset.cancel){if(!confirm('Отменить эту пробную запись? Время снова станет доступно.'))return;if(await mutate(s=>{const r=s.bookings.find(x=>x.id===b.dataset.cancel);if(r?.status==='confirmed')r.status='cancelled'})){render();feedback('Пробная запись отменена.')}return}if(b.dataset.resetDay){if(await mutate(s=>{delete s.exceptions[b.dataset.resetDay];rejectConflicts(s)})){render();feedback('Обычный график восстановлен.')}}});
$('.dialog-close').onclick=()=>$('#client-dialog').close();window.addEventListener('storage',render);window.addEventListener('hashchange',()=>{const n=location.hash.slice(1);if(labels[n]&&n!==view){view=n;search='';render()}});render();
